using System.Windows.Threading;
using Microsoft.Win32;
namespace MooView;

public partial class MainWindow : Window
{
    internal readonly TextBlock TitleLabel=new(),DetailLabel=new();
    readonly List<string> files = []; readonly HashSet<string> selected = new(StringComparer.OrdinalIgnoreCase); readonly Dictionary<string, BitmapSource> cache = new(StringComparer.OrdinalIgnoreCase); readonly List<ImagePane> panes = []; int index, loadVersion; bool ready, dark, checker = true, full, playing, listUpdating, loading; string bgColor = "#353B37"; double zoom = 100; WindowState oldState; WindowStyle oldStyle; ResizeMode oldResize; Thickness oldMargin; bool nav = false; bool gifPaused; readonly DispatcherTimer playTimer = new(); readonly DispatcherTimer hideTimer = new() { Interval = TimeSpan.FromMilliseconds(1700) }; DateTime lastWheel = DateTime.MinValue; Point lastMouse = new(-100, -100); readonly string settingsPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "MooView", "settings.json");
    public MainWindow(bool testMode = false) { InitializeComponent(); ready = true; playTimer.Tick += async (_, _) => { if (loading) return; if (index >= files.Count - 1 && LoopCheck.IsChecked != true) { Stop(); return; } index = (index + 1) % Math.Max(1, files.Count); await RenderAsync(); }; hideTimer.Tick += (_, _) => { if (!ViewToolbar.IsMouseOver && !BottomBar.IsMouseOver) { SetChrome(false); hideTimer.Stop(); } }; if (!testMode) { LoadSettings(); Closing += (_, _) => SaveSettings(); } UpdateLanguage(); ApplyNav(); BuildPanes(); PlayButton.Content=Glyph.Label("play","재생"); Closed+=(_,_)=>{playTimer.Stop();hideTimer.Stop();foreach(var pane in panes)pane.StopAnimation();}; }
    public void OpenPaths(IEnumerable<string> paths) { try { var input = paths.ToArray(); string? initial = input.Length == 1 && File.Exists(input[0]) ? Path.GetFullPath(input[0]) : null; if (initial != null) input = new[] { Path.GetDirectoryName(initial)! }; var found = input.SelectMany(p => Directory.Exists(p) ? Directory.EnumerateFiles(p) : new[] { p }).Where(p => File.Exists(p) && Imaging.Extensions.Contains(Path.GetExtension(p))).Select(Path.GetFullPath).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(p => p, NaturalComparer.Instance).ToList(); if (found.Count == 0) { Status(L10n.T("NoImages")); return; } Stop(); files.Clear(); files.AddRange(found); cache.Clear(); selected.Clear(); index = initial == null ? 0 : Math.Max(0, files.FindIndex(p => p.Equals(initial, StringComparison.OrdinalIgnoreCase))); FolderLabel.Text = Path.GetDirectoryName(files[0]); Search.Text = ""; RebuildList(); _ = RenderAsync(); Keyboard.Focus(Root); } catch (Exception ex) { Error(ex); } }
    void OpenFiles(object s, RoutedEventArgs e) { var d = new OpenFileDialog { Multiselect = true, Filter = "이미지|*.jpg;*.jpeg;*.png;*.bmp;*.gif;*.tif;*.tiff;*.ico;*.webp;*.wdp;*.jxr|모든 파일|*.*" }; if (d.ShowDialog(this) == true) { if (d.FileNames.Length == 1) { string chosen = d.FileName; OpenPaths(new[] { chosen }); } else OpenPaths(d.FileNames); } }
    void OpenFolder(object s, RoutedEventArgs e) { var d = new OpenFolderDialog { Title = L10n.T("Folder") }; if (d.ShowDialog(this) == true) OpenPaths(new[] { d.FolderName }); }
    void OnDrop(object s, DragEventArgs e) { if (e.Data.GetData(DataFormats.FileDrop) is string[] paths) OpenPaths(paths); }
    void SearchChanged(object s, TextChangedEventArgs e) { if (ready) RebuildList(); }
    void RebuildList() { listUpdating = true; FileList.Items.Clear(); foreach (var p in files.Where(p => Path.GetFileName(p).Contains(Search.Text, StringComparison.OrdinalIgnoreCase))) { var row = new DockPanel { Margin = new Thickness(0, 5, 0, 5) }; var check = new CheckBox { IsChecked = selected.Contains(p), VerticalAlignment = VerticalAlignment.Center }; check.Click += (_, _) => { if (check.IsChecked == true) selected.Add(p); else selected.Remove(p); SelectionLabel.Text = $"{selected.Count} "+L10n.T("Selected"); }; row.Children.Add(check); var label = new TextBlock { Text = Path.GetFileName(p), TextTrimming = TextTrimming.CharacterEllipsis, VerticalAlignment = VerticalAlignment.Center, ToolTip = p }; row.Children.Add(label); var item = new ListBoxItem { Content = row, Tag = p, Padding = new Thickness(3), HorizontalContentAlignment = HorizontalAlignment.Stretch }; item.SetResourceReference(ForegroundProperty, "Text"); FileList.Items.Add(item); } SelectionLabel.Text = $"{selected.Count}개 선택됨"; listUpdating = false; SyncSelection(); }
    void SyncSelection() { listUpdating = true; foreach (ListBoxItem item in FileList.Items) if ((string)item.Tag == (files.Count > 0 ? files[index] : "")) { FileList.SelectedItem = item; FileList.ScrollIntoView(item); break; } listUpdating = false; }
    void FileChosen(object s, SelectionChangedEventArgs e) { if (!ready || listUpdating || FileList.SelectedItem is not ListBoxItem item) return; index = files.IndexOf((string)item.Tag); _ = RenderAsync(); }
    void SelectAllFiles(object s, RoutedEventArgs e) { foreach (var p in files.Where(p => Path.GetFileName(p).Contains(Search.Text, StringComparison.OrdinalIgnoreCase))) selected.Add(p); RebuildList(); }
    void ClearSelection(object s, RoutedEventArgs e) { selected.Clear(); RebuildList(); }
    string[] Targets() => selected.Count > 0 ? files.Where(selected.Contains).ToArray() : files.Count > 0 ? new[] { files[index] } : [];
    async Task<BitmapSource> LoadAsync(string path) { if (cache.TryGetValue(path, out var b)) return b; b = await Task.Run(() => Imaging.Load(path)); cache[path] = b; return b; }
    async Task RenderAsync() { if (!ready) return; int version = ++loadVersion; loading = true; foreach(var p in panes)p.StopAnimation(); try { EmptyState.Visibility = files.Count == 0 ? Visibility.Visible : Visibility.Collapsed; if (files.Count == 0) return; var current = files[index]; TitleLabel.Text = Path.GetFileName(current); Title=Path.GetFileName(current)+" — MooView"; CounterLabel.Text = $"{index + 1:000} / {files.Count:000}  ·  {panes.Count} PAGE"; for (int i = 0; i < panes.Count; i++) { int pos = index + i; var pane = panes[i]; pane.Visibility = pos < files.Count ? Visibility.Visible : Visibility.Hidden; if (pos >= files.Count) continue; try { string path=files[pos]; BitmapSource b; if(Path.GetExtension(path).Equals(".gif",StringComparison.OrdinalIgnoreCase)){var data=await Task.Run(()=>GifData.Load(path));if(version!=loadVersion)return;pane.SetAnimation(data);pane.SetAnimationRunning(!gifPaused);b=pane.CurrentBitmap!;var first=b.Clone();first.Freeze();cache[path]=first;}else{b=await LoadAsync(path);if(version!=loadVersion)return;pane.SetImage(b);} if (i == 0) DetailLabel.Text = $"{b.PixelWidth:N0} × {b.PixelHeight:N0}  ·  {Path.GetExtension(current).TrimStart('.').ToUpper()}  ·  {new FileInfo(current).Length / 1024.0:N0} KB"; } catch (Exception ex) { if (version != loadVersion) return; pane.Visibility = Visibility.Hidden; Status(L10n.Choose("이미지를 열 수 없습니다: ","Unable to open image: ") + ex.Message); } } if (version != loadVersion) return; GifButton.Visibility=panes.Any(p=>p.IsAnimated)?Visibility.Visible:Visibility.Collapsed; UpdateExif(); SyncSelection(); var keep = files.Skip(Math.Max(0, index - 2)).Take(12).ToHashSet(StringComparer.OrdinalIgnoreCase); foreach (var key in cache.Keys.ToArray()) if (!keep.Contains(key)) cache.Remove(key); _ = Prefetch(index, version); } finally { if (version == loadVersion) loading = false; } }
    async Task Prefetch(int start, int version) { for (int i = start + panes.Count; i < Math.Min(files.Count, start + panes.Count + 3); i++) { if (version != loadVersion) return; string p = files[i]; if (cache.ContainsKey(p)) continue; try { var b = await Task.Run(() => Imaging.Load(p)); if (version == loadVersion) cache[p] = b; } catch { } } }
    void BuildPanes() { if (!ready) return; foreach(var old in panes)old.StopAnimation(); Pages.Children.Clear(); Pages.RowDefinitions.Clear(); Pages.ColumnDefinitions.Clear(); panes.Clear(); int n = PageCount.SelectedIndex + 1; int cols = LayoutMode.SelectedIndex == 0 ? n : LayoutMode.SelectedIndex == 2 ? 1 : n == 1 ? 1 : 2; int rows = (n + cols - 1) / cols; for (int i = 0; i < cols; i++) Pages.ColumnDefinitions.Add(new ColumnDefinition()); for (int i = 0; i < rows; i++) Pages.RowDefinitions.Add(new RowDefinition()); for (int i = 0; i < n; i++) { var p = new ImagePane(); p.Navigate += step => { if ((DateTime.UtcNow - lastWheel).TotalMilliseconds < 65) return; lastWheel = DateTime.UtcNow; Move(step); }; p.ZoomRequested += SetZoom; p.SetZoom(FitMode.SelectedIndex, zoom); Grid.SetColumn(p, i % cols); Grid.SetRow(p, i / cols); Pages.Children.Add(p); panes.Add(p); } UpdateBackground(); }
    void ViewChanged(object s, SelectionChangedEventArgs e) { if (!ready) return; BuildPanes(); _ = RenderAsync(); }
    void ZoomChanged(object s, SelectionChangedEventArgs e) { if (!ready) return; foreach (var p in panes) p.SetZoom(FitMode.SelectedIndex, zoom); }
    void SetZoom(double value) { zoom = Math.Clamp(value, 1, 3200); ZoomInput.Text = zoom.ToString("0.#"); FitMode.SelectedIndex = 4; foreach (var p in panes) p.SetZoom(4, zoom); }
    void ZoomEntered(object s, KeyEventArgs e) { if (e.Key == Key.Enter) { if (double.TryParse(ZoomInput.Text, out double z)) SetZoom(z); e.Handled = true; Keyboard.ClearFocus(); } }
    void ZoomOut(object s, RoutedEventArgs e) => SetZoom(zoom / 1.2); void ZoomIn(object s, RoutedEventArgs e) => SetZoom(zoom * 1.2);
    void Previous(object s, RoutedEventArgs e) => Move(-1); void Next(object s, RoutedEventArgs e) => Move(1);
    void Move(int step) { if (files.Count == 0) return; index = (index + step + files.Count) % files.Count; _ = RenderAsync(); }
    void ToggleNav(object s, RoutedEventArgs e) { nav = !nav; ApplyNav(); }
    void ApplyNav() { if (full) return; Sidebar.Visibility = nav ? Visibility.Visible : Visibility.Collapsed; Root.ColumnDefinitions[1].Width = new GridLength(nav ? 250 : 0); }
    void ToggleAlpha(object s, RoutedEventArgs e) { checker = !checker; UpdateBackground(); }
    void UpdateBackground() { bgColor=dark?"#252D27":"#E1E3E0"; Pages.Background = Imaging.Background(checker, bgColor, dark); AlphaButton.Content = Glyph.Label("alpha",checker ? "체크보드" : "단색"); }
    void ToggleLanguage(object s,RoutedEventArgs e){L10n.Instance.English=!L10n.Instance.English;UpdateLanguage();}
    void UpdateLanguage(){if(files.Count==0)FolderLabel.Text=L10n.T("Library");UpdateExif();SelectionLabel.Text=$"{selected.Count} "+L10n.T("Selected");StatusLabel.Text=L10n.T("Shortcuts");}
    void ToggleTheme(object s, RoutedEventArgs e) { dark = !dark; ApplyTheme(); }
    void ApplyTheme() { var colors = dark ? new[] { "#262D29", "#323A34", "#E5EBE3", "#B6C3B9", "#465149", "#252D27", "#3B604B" } : new[] { "#D9DBD8", "#E1E3E0", "#242925", "#566159", "#F1F3EF", "#D0D4CE", "#BAD8C9" }; var keys = new[] { "Bg", "Panel", "Text", "Muted", "Line", "Field", "Accent" }; for (int i = 0; i < keys.Length; i++) Application.Current.Resources[keys[i]] = new SolidColorBrush((Color)ColorConverter.ConvertFromString(colors[i])); UpdateBackground(); }
    void ToggleExif(object s, RoutedEventArgs e) { ExifPanel.Visibility = ExifPanel.Visibility == Visibility.Visible ? Visibility.Collapsed : Visibility.Visible; UpdateExif(); }
    void UpdateExif() { if (ExifPanel.Visibility == Visibility.Visible && files.Count > 0) { cache.TryGetValue(files[index], out var b); ExifText.Text = Imaging.Metadata(files[index], b); } }
    void CopyExif(object s, RoutedEventArgs e) { try { Clipboard.SetText(ExifText.Text); Status(L10n.T("Copied")); } catch (Exception ex) { Error(ex); } }
    void ToggleGif(object s,RoutedEventArgs e){gifPaused=!gifPaused;foreach(var p in panes)p.SetAnimationRunning(!gifPaused);GifButton.Content=Glyph.Label(gifPaused?"play":"pause",gifPaused?"GIF 재생":"GIF 정지");}
    void TogglePlay(object s, RoutedEventArgs e) { if (playing) { Stop(); return; } if (files.Count == 0) return; if (!double.TryParse(FpsInput.Text, out double fps) || fps < .1 || fps > 30) { Status(L10n.T("InvalidFps")); return; } playing = true; playTimer.Interval = TimeSpan.FromSeconds(1 / fps); playTimer.Start(); PlayButton.Content = Glyph.Label("pause","정지"); System.Windows.Automation.AutomationProperties.SetName(PlayButton,"정지"); Status(L10n.Choose($"목표 {fps:0.#} fps · 디코딩 시간에 따라 달라집니다.",$"Target {fps:0.#} fps · Actual speed depends on decoding time.")); }
    void Stop() { playing = false; playTimer.Stop(); PlayButton.Content = Glyph.Label("play","재생"); System.Windows.Automation.AutomationProperties.SetName(PlayButton,"재생"); }
    void ToggleFull(object s, RoutedEventArgs e) => SetFull(!full);
    void SetFull(bool value) { if (full == value) return; full = value; Keyboard.Focus(Root); if (full) { oldState = WindowState; oldStyle = WindowStyle; oldResize = ResizeMode; oldMargin = Root.Margin; WindowState = WindowState.Normal; WindowStyle = WindowStyle.None; ResizeMode = ResizeMode.NoResize; WindowState = WindowState.Maximized; Root.Margin = new Thickness(0); Rail.Visibility = Sidebar.Visibility = Visibility.Collapsed; Root.ColumnDefinitions[0].Width = new GridLength(0); Root.ColumnDefinitions[1].Width = new GridLength(0); Grid.SetRow(Stage, 0); Grid.SetRowSpan(Stage, 2); Stage.CornerRadius = new CornerRadius(0);  BottomBar.Margin = new Thickness(14); ExifPanel.Visibility = Visibility.Collapsed; ViewToolbar.Margin = new Thickness(10, 8, 10, 8); SetChrome(false); } else { hideTimer.Stop(); ViewToolbar.Margin = new Thickness(10, 8, 10, 8); WindowState = WindowState.Normal; WindowStyle = oldStyle; ResizeMode = oldResize; WindowState = oldState; Root.Margin = oldMargin; Root.ColumnDefinitions[0].Width = new GridLength(72); Rail.Visibility = Visibility.Visible; ApplyNav(); Grid.SetRow(Stage, 0); Grid.SetRowSpan(Stage, 1); Stage.CornerRadius = new CornerRadius(20);  BottomBar.Margin = new Thickness(0, 14, 0, 0); SetChrome(true); } }
    void SetChrome(bool visible) { var v = visible ? Visibility.Visible : Visibility.Collapsed; BottomBar.Visibility = ViewToolbar.Visibility = v; if (full) Cursor = visible ? Cursors.Arrow : Cursors.None; else Cursor = Cursors.Arrow; }
    void OnMouseMove(object s, MouseEventArgs e) { var p = e.GetPosition(Root); if (Math.Abs(p.X - lastMouse.X) + Math.Abs(p.Y - lastMouse.Y) < 2) return; lastMouse = p; if (!full) return; Cursor = Cursors.Arrow; if (p.Y < 88) { SetChrome(true); hideTimer.Stop(); hideTimer.Start(); } else { hideTimer.Stop(); hideTimer.Start(); } }
    void OnMouseButton(object s, MouseButtonEventArgs e) { if (e.ChangedButton == MouseButton.Middle) { SetFull(!full); e.Handled = true; } }
    void OnKey(object s, KeyEventArgs e) { if (e.Key == Key.Escape) { if (full) SetFull(false); else Stop(); e.Handled = true; return; } if (e.Key == Key.F11) { SetFull(!full); e.Handled = true; return; } if (e.Key == Key.O && Keyboard.Modifiers.HasFlag(ModifierKeys.Control)) { OpenFiles(this, e); e.Handled = true; return; } if (!full && (Keyboard.FocusedElement is TextBox || Keyboard.FocusedElement is ComboBox)) return; switch (e.Key) { case Key.Space: case Key.Right: case Key.PageDown: Move(1); break; case Key.Left: case Key.PageUp: Move(-1); break; case Key.Home: index = 0; _ = RenderAsync(); break; case Key.End: index = Math.Max(0, files.Count - 1); _ = RenderAsync(); break; case Key.Tab: ToggleNav(this, e); break; case Key.I: ToggleExif(this, e); break; case Key.E: EditImage(this, e); break; case Key.P: TogglePlay(this, e); break; case Key.D: ToggleTheme(this, e); break; case Key.O: if (Keyboard.Modifiers.HasFlag(ModifierKeys.Control)) OpenFiles(this, e); else return; break; default: return; } e.Handled = true; }
    async void EditImage(object s, RoutedEventArgs e) { if (files.Count == 0) return; Stop(); try { var source = files[index]; var b = await LoadAsync(source); var edit = new EditorWindow(b, source) { Owner = this }; edit.ShowDialog(); if (edit.SavedPath is string saved) { cache.Remove(saved); if (!files.Contains(saved, StringComparer.OrdinalIgnoreCase)) files.Insert(index + 1, saved); index = files.FindIndex(p => p.Equals(saved, StringComparison.OrdinalIgnoreCase)); RebuildList(); await RenderAsync(); } } catch (Exception ex) { Error(ex); } }
    async void BatchConvert(object s, RoutedEventArgs e) { var targets = Targets(); if (targets.Length == 0) return; Stop(); var fmt = Dialogs.Choose(this, L10n.T("Convert"), L10n.Choose($"{targets.Length}개 이미지의 저장 포맷",$"Export format for {targets.Length} images"), new[] { "PNG (.png)", "JPEG (.jpg)", "BMP (.bmp)", "TIFF (.tiff)", "GIF (.gif)" }); if (fmt < 0) return; var d = new OpenFolderDialog { Title = L10n.Choose("변환 결과를 저장할 폴더","Choose the export folder") }; if (d.ShowDialog(this) != true) return; string ext = new[] { ".png", ".jpg", ".bmp", ".tiff", ".gif" }[fmt]; var errors = new List<string>(); int success = 0; foreach (var p in targets) { try { var b = await Task.Run(() => Imaging.Load(p)); string name = Path.Combine(d.FolderName, Path.GetFileNameWithoutExtension(p) + ext); int n = 1; while (File.Exists(name)) name = Path.Combine(d.FolderName, Path.GetFileNameWithoutExtension(p) + $"_{n++}" + ext); Imaging.Save(b, name); success++; Status(L10n.Choose($"변환 중 {success}/{targets.Length}",$"Converting {success}/{targets.Length}")); await Dispatcher.Yield(DispatcherPriority.Background); } catch (Exception ex) { errors.Add(Path.GetFileName(p) + ": " + ex.Message); } } Status(L10n.Choose($"{success}개 변환 완료 · {d.FolderName}",$"Converted {success} images · {d.FolderName}")); if (errors.Count > 0) MessageBox.Show(this, string.Join("\n", errors), L10n.Choose("변환하지 못한 파일","Files that could not be converted")); }
    void BatchRename(object s, RoutedEventArgs e) { var src = Targets(); if (src.Length == 0) return; Stop(); var pattern = Dialogs.Ask(this, L10n.T("Rename"), L10n.Choose("{name}: 원래 이름 · {n}: 001부터 시작하는 번호\n확장자는 유지됩니다.","{name}: original name · {n}: number starting at 001\nExtensions are preserved."), "Image_{n}"); if (pattern == null) return; try { if (pattern.Contains('/') || pattern.Contains('\\')) throw new ArgumentException(L10n.Choose("이름에는 경로를 넣을 수 없습니다.","A filename cannot contain a path.")); var dst = Imaging.RenameTargets(src, pattern, 1); string preview = string.Join("\n", src.Zip(dst, (a, b) => Path.GetFileName(a) + "  →  " + Path.GetFileName(b))); if (!Dialogs.Confirm(this, L10n.Choose("이름 변경 미리보기","Rename preview"), preview + L10n.Choose("\n\n위 파일 이름을 실제로 변경합니다.","\n\nApply these filename changes?"))) return; Imaging.Rename(src, dst); for (int i = 0; i < src.Length; i++) { int at = files.IndexOf(src[i]); files[at] = dst[i]; selected.Remove(src[i]); selected.Add(dst[i]); } cache.Clear(); RebuildList(); _ = RenderAsync(); Status(L10n.Choose($"{src.Length}개 파일 이름을 변경했습니다.",$"Renamed {src.Length} files.")); } catch (Exception ex) { Error(ex); } }
    void Status(string text) => StatusLabel.Text = text; void Error(Exception ex) { Status(ex.Message); MessageBox.Show(this, ex.Message, "MooView", MessageBoxButton.OK, MessageBoxImage.Information); }
    void SetDefaultApp(object s, RoutedEventArgs e) { try { FileAssociation.Register(); Status(L10n.T("DefaultHint")); } catch (Exception ex) { Error(ex); } }
    void ShowHelp(object s, RoutedEventArgs e) => Dialogs.Info(this, L10n.T("Help"), L10n.Instance.English ? "Wheel / arrows / Space: navigate images\nCtrl+wheel: zoom. Drag or use the minimap to pan.\nMiddle click / F11: fullscreen. Esc: exit fullscreen.\nFullscreen menus appear only when moving the mouse near the top edge.\nTab: toggle file sidebar. I: EXIF. D: theme. E: edit. P: slideshow.\nThe language icon at the bottom of the left rail switches Korean / English.\n\nGIF files play with their original timing and repeat count.\nUse the GIF pause button to pause or resume.\nSelect files with the sidebar checkboxes for batch convert / rename.\n\nEditor: add text, then select and drag it. Resize with the corner handle, rotate with the top circle or numeric controls. Double-click to edit the text; Delete removes it.\nThe eraser removes parts of drawing strokes without changing the original image.\nText and strokes stay editable during the editor session, including after saving. Saved images contain flattened pixels, not layers.\n\nSlideshow supports a target rate up to 30 fps; actual speed depends on image decoding and hardware.\nGIF editing/conversion uses the first frame; TIFF uses the first page.\nWebP requires a compatible Windows WIC codec.\nExport: PNG, JPEG, BMP, TIFF, GIF. Metadata is not copied to edited/exported images. JPEG transparency is flattened onto white." : "휠 / Space / → : 다음 이미지\n휠 위로 / ← : 이전 이미지\nCtrl + 휠 : 포인터가 있는 이미지 기준 확대율 조절\n확대한 이미지 드래그 / 우측 아래 미니맵 : 위치 이동\n휠 클릭 / F11 : 전체화면\nEsc : 전체화면 해제 (일반 화면에서는 재생 정지)\nTab : 탐색 패널 토글\nI : EXIF 표시 · D : 테마 전환\nE : 편집 · P : 재생/정지 · Ctrl+O : 열기\nHome / End : 처음 / 마지막 이미지\n\n전체화면에서는 상단에 마우스를 움직일 때 메뉴가 표시됩니다.\n키보드와 휠 탐색은 메뉴를 표시하지 않습니다.\n\n파일 목록의 체크박스로 여러 파일을 선택하세요.\n선택이 없으면 현재 이미지에 일괄 작업을 적용합니다.\n단일 파일을 열면 같은 폴더의 이미지도 탐색할 수 있습니다.\n페이지 수는 연속 이미지를 함께 보여주며 한 장씩 이동합니다.\n\nGIF는 원본 프레임 시간과 반복 횟수로 자동 재생합니다. GIF 정지 버튼으로 멈출 수 있습니다.\nGIF 편집/변환은 첫 프레임, TIFF는 첫 페이지를 사용합니다.\n자동 재생은 폴더의 이미지 시퀀스 재생입니다.\nWebP는 Windows WIC 코덱이 설치되어 있어야 열립니다.\n변환 포맷: PNG, JPEG, BMP, TIFF, GIF.\n편집/변환 출력에는 원본 EXIF가 보존되지 않습니다.\nJPEG 저장 시 투명 영역은 흰색으로 합성됩니다.\n최대 30fps는 목표 속도이며 파일 크기와 장치 성능에 따라 달라집니다.");
    void LoadSettings() { try { if (!File.Exists(settingsPath)) return; var p = System.Text.Json.JsonSerializer.Deserialize<Preferences>(File.ReadAllText(settingsPath)); if (p == null) return; dark = p.Dark; checker = p.Checker; bgColor = p.Background; nav = p.Nav; L10n.Instance.English=p.English; ApplyTheme(); ApplyNav(); } catch { } }
    void SaveSettings() { try { Directory.CreateDirectory(Path.GetDirectoryName(settingsPath)!); File.WriteAllText(settingsPath, System.Text.Json.JsonSerializer.Serialize(new Preferences(dark, checker, bgColor, nav,L10n.Instance.English))); } catch { } }
    record Preferences(bool Dark, bool Checker, string Background, bool Nav,bool English=false);
}
public sealed class NaturalComparer : IComparer<string> { public static readonly NaturalComparer Instance = new(); public int Compare(string? a, string? b) { a ??= ""; b ??= ""; int x = 0, y = 0; while (x < a.Length && y < b.Length) { if (char.IsDigit(a[x]) && char.IsDigit(b[y])) { int sx = x, sy = y; while (x < a.Length && char.IsDigit(a[x])) x++; while (y < b.Length && char.IsDigit(b[y])) y++; string aa = a[sx..x].TrimStart('0'), bb = b[sy..y].TrimStart('0'); int r = aa.Length.CompareTo(bb.Length); if (r != 0) return r; r = string.Compare(aa, bb, StringComparison.Ordinal); if (r != 0) return r; } else { int r = char.ToUpperInvariant(a[x++]).CompareTo(char.ToUpperInvariant(b[y++])); if (r != 0) return r; } } return a.Length.CompareTo(b.Length); } }





